  "fact_or_values": "fact",
  "verdict": "Unproven",
  "steelman": "The nonpartisan Congressional Budget Office projected in official reports analyzing legislation to raise the federal minimum wage to $15 per hour that employment would decline by an estimated 1.3 million to 1.4 million workers by 2025.",
  "finding": "The Congressional Budget Office estimated that raising the federal minimum wage under the $15 option would reduce employment by 1.4 million workers, or 0.9 percent, according to its average estimate for an average week in 2025. In an earlier evaluation, the agency projected a median reduction of 1.3 million workers, with a likely range between about zero and a reduction of 3.7 million workers. Because this claim is a forward-looking economic simulation rather than an observed count, and published research ranges from finding little or no employment effect to finding substantial job losses, the actual impact cannot be verified.",
  "reasoning_flags": [
    "Forecast, not a finding"
  ],
  "newest_data": "Congressional Budget Office report 'The Budgetary Effects of the Raise the Wage Act of 2021', published February 8, 2021, and its underlying July 8, 2019 study 'The Effects on Employment and Family Income of Increasing the Federal Minimum Wage'. Subsequent CBO analyses, including its December 18, 2023 estimate for S. 2488 and January 30, 2024 interactive tool update, examined proposals targeting a $17 minimum wage rather than $15; a freshness check confirmed no newer official CBO evaluation of a $15 federal minimum wage exists.",
  "figures": [
    {
      "value": "1.4 million",
      "unit": "workers",
      "label": "CBO average estimate of employment reduction by 2025",
      "quote": 1
    },
    {
