    {
      "url": "https://vertexaisearch.cloud.google.com/grounding-api-redirect/AUZIYQFjNsiyphnG9MOyZMhrKwA-uUORM3EW2OzhP3Z7Br8xeDVZW1wu1Yd5kpH_8JY2PWn62Ls9G7cXlhs2TCxSvJMELqkQ_HoJEkIqMFdVkoqXH1H__-hOqjaUFZ97",
      "publisher": "Congressional Budget Office",
      "published": "2021-02-08",
      "quote": "Employment would be reduced by 1.4 million workers, or 0.9 percent, according to CBO's average estimate; and The number of people in poverty would be reduced by 0.9 million.",
      "role": "context"
    },
    {
      "url": "https://vertexaisearch.cloud.google.com/grounding-api-redirect/AUZIYQE_MQ2d_Ec138A8XSfWflyRd5Ckg8G9atOulQ3w5XGHbnZ2bfqF1IP_20HGvegWi2cwIyW2EuiTNzSQXQBRWGXArGQ6LOqXgU-1vlQpLl6WZ3-RL0LP5Wtos8M0",
      "publisher": "Congressional Budget Office",
      "published": "2019-07-08",
      "quote": "According to CBO's median estimate, under the $15 option, 1.3 million workers who would otherwise be employed would be jobless in an average week in 2025. (That would equal a 0.8 percent reduction in the number of employed workers.) CBO estimates that there is about a two-thirds chance that the change in employment would lie between about zero and a reduction of 3.7 million workers (see table below).",
      "role": "context"
    },
    {
      "url": "https://vertexaisearch.cloud.google.com/grounding-api-redirect/AUZIYQE_MQ2d_Ec138A8XSfWflyRd5Ckg8G9atOulQ3w5XGHbnZ2bfqF1IP_20HGvegWi2cwIyW2EuiTNzSQXQBRWGXArGQ6LOqXgU-1vlQpLl6WZ3-RL0LP5Wtos8M0",
      "publisher": "Congressional Budget Office",
      "published": "2019-07-08",
      "quote": "Findings in the research literature about how changes in the federal minimum wage affect employment vary widely. Many studies have found little or no effect of minimum wages on employment, but many others have found substantial reductions in employment.",
      "role": "context"
    }
  ]
}
